pub(super) const CS_BODY: &str = "#version 420\n#extension GL_ARB_compute_shader          : require\n\nlayout(local_size_x = 2, local_size_y = 2, local_size_z = 2) in;\n\nlayout(rgba32f) uniform image2D testImage;\n\nuniform double cs_double;\nuniform dvec2  cs_dvec2;\nuniform dvec3  cs_dvec3;\nuniform dvec4  cs_dvec4;\nuniform double cs_double_arr[2];\nuniform dvec2  cs_dvec2_arr [2];\nuniform dvec3  cs_dvec3_arr [2];\nuniform dvec4  cs_dvec4_arr [2];\n\nuniform struct cs_struct\n{\n    double struct_double;\n    dvec2  struct_dvec2;\n    dvec3  struct_dvec3;\n    dvec4  struct_dvec4;\n} cs_array[2];\n\nvoid main()\n{\n    double tmp = cs_double                  * cs_dvec2.x                 * cs_dvec3.y                 * cs_dvec4.z                 *\n                 cs_double_arr[0]           * cs_dvec2_arr[0].x          * cs_dvec3_arr[0].z          * cs_dvec4_arr[0].w          *\n                 cs_double_arr[1]           * cs_dvec2_arr[1].x          * cs_dvec3_arr[1].z          * cs_dvec4_arr[1].w          *\n                 cs_array[0].struct_double  * cs_array[0].struct_dvec2.y * cs_array[0].struct_dvec3.z * cs_array[0].struct_dvec4.w *\n                 cs_array[1].struct_double  * cs_array[1].struct_dvec2.y * cs_array[1].struct_dvec3.z * cs_array[1].struct_dvec4.w;\n\n    imageStore(testImage, ivec2(0, 0), (tmp > 1.0) ? vec4(1.0) : vec4(0.0) );\n}\n";

pub(super) const VS_BODY: &str = "#version 400\n\nuniform double vs_double;\nuniform dvec2  vs_dvec2;\nuniform dvec3  vs_dvec3;\nuniform dvec4  vs_dvec4;\nuniform double vs_double_arr[2];\nuniform dvec2  vs_dvec2_arr [2];\nuniform dvec3  vs_dvec3_arr [2];\nuniform dvec4  vs_dvec4_arr [2];\n\nuniform struct vs_struct\n{\n    double struct_double;\n    dvec2  struct_dvec2;\n    dvec3  struct_dvec3;\n    dvec4  struct_dvec4;\n} vs_array[2];\n\nvoid main()\n{\n    if (vs_double                 * vs_dvec2.x                 * vs_dvec3.x                 * vs_dvec4.x                 *\n        vs_double_arr[0]          * vs_dvec2_arr[0].x          * vs_dvec3_arr[0].x          * vs_dvec4_arr[0].x          *\n        vs_double_arr[1]          * vs_dvec2_arr[1].x          * vs_dvec3_arr[1].x          * vs_dvec4_arr[1].x          *\n        vs_array[0].struct_double * vs_array[0].struct_dvec2.x * vs_array[0].struct_dvec3.x * vs_array[0].struct_dvec4.x *\n        vs_array[1].struct_double * vs_array[1].struct_dvec2.x * vs_array[1].struct_dvec3.x * vs_array[1].struct_dvec4.x > 1.0)\n    {\n        gl_Position = vec4(0);\n    }\n    else\n    {\n        gl_Position = vec4(1);\n    }\n}\n";

pub(super) const TC_BODY: &str = "#version 400\n\nuniform double tc_double;\nuniform dvec2  tc_dvec2;\nuniform dvec3  tc_dvec3;\nuniform dvec4  tc_dvec4;\nuniform double tc_double_arr[2];\nuniform dvec2  tc_dvec2_arr [2];\nuniform dvec3  tc_dvec3_arr [2];\nuniform dvec4  tc_dvec4_arr [2];\n\nuniform struct tc_struct\n{\n    double struct_double;\n    dvec2  struct_dvec2;\n    dvec3  struct_dvec3;\n    dvec4  struct_dvec4;\n} tc_array[2];\n\nlayout(vertices = 4) out;\n\nvoid main()\n{\n    gl_TessLevelOuter[0] = (tc_double        > 1.0) ? 2.0 : 3.0;\n    gl_TessLevelOuter[1] = (tc_dvec2.x       > 1.0) ? 3.0 : 4.0;\n    gl_TessLevelOuter[2] = (tc_dvec3.x       > 1.0) ? 4.0 : 5.0;\n    gl_TessLevelOuter[3] = (tc_dvec4.x       > 1.0) ? 5.0 : 6.0;\n    gl_TessLevelInner[0] = (tc_double_arr[0] > 1.0) ? 6.0 : 7.0;\n    gl_TessLevelInner[1] = (tc_double_arr[1] > 1.0) ? 7.0 : 8.0;\n\n    if (tc_dvec2_arr[0].y          * tc_dvec2_arr[1].y          *\n        tc_dvec3_arr[0].z          * tc_dvec3_arr[1].z          *\n        tc_dvec4_arr[0].z          * tc_dvec4_arr[1].z          *\n        tc_array[0].struct_double  * tc_array[0].struct_dvec2.x * \n        tc_array[0].struct_dvec3.y * tc_array[0].struct_dvec4.z * \n        tc_array[1].struct_double  * tc_array[1].struct_dvec2.x * \n        tc_array[1].struct_dvec3.y * tc_array[1].struct_dvec4.z > 0.0)\n    {\n        gl_TessLevelInner[1] = 3.0;\n        gl_out[gl_InvocationID].gl_Position = gl_in[gl_InvocationID].gl_Position;\n    }\n    else\n    {\n        gl_TessLevelInner[1] = 0.0;\n        gl_out[gl_InvocationID].gl_Position = gl_in[gl_InvocationID].gl_Position + vec4(1);\n    }\n}\n";

pub(super) const TE_BODY: &str = "#version 400\n\nuniform double te_double;\nuniform dvec2  te_dvec2;\nuniform dvec3  te_dvec3;\nuniform dvec4  te_dvec4;\nuniform double te_double_arr[2];\nuniform dvec2  te_dvec2_arr [2];\nuniform dvec3  te_dvec3_arr [2];\nuniform dvec4  te_dvec4_arr [2];\n\nuniform struct te_struct\n{\n    double struct_double;\n    dvec2  struct_dvec2;\n    dvec3  struct_dvec3;\n    dvec4  struct_dvec4;\n} te_array[2];\n\nlayout(triangles) in;\n\nvoid main()\n{\n    if (te_double                 * te_dvec2.x                 * te_dvec3.x                 * te_dvec4.x                 *\n        te_double_arr[0]          * te_dvec2_arr[0].x          * te_dvec3_arr[0].x          * te_dvec4_arr[0].x          *\n        te_double_arr[1]          * te_dvec2_arr[1].x          * te_dvec3_arr[1].x          * te_dvec4_arr[1].x          *\n        te_array[0].struct_double * te_array[0].struct_dvec2.x * te_array[0].struct_dvec3.x * te_array[0].struct_dvec4.x *\n        te_array[1].struct_double * te_array[1].struct_dvec2.x * te_array[1].struct_dvec3.x * te_array[1].struct_dvec4.x > 1.0)\n    {\n        gl_Position = gl_in[0].gl_Position;\n    }\n    else\n    {\n        gl_Position = gl_in[0].gl_Position + vec4(1);\n    }\n}\n";

pub(super) const GS_BODY: &str = "#version 400\n\nuniform double gs_double;\nuniform dvec2  gs_dvec2;\nuniform dvec3  gs_dvec3;\nuniform dvec4  gs_dvec4;\nuniform double gs_double_arr[2];\nuniform dvec2  gs_dvec2_arr [2];\nuniform dvec3  gs_dvec3_arr [2];\nuniform dvec4  gs_dvec4_arr [2];\n\nuniform struct gs_struct\n{\n    double struct_double;\n    dvec2  struct_dvec2;\n    dvec3  struct_dvec3;\n    dvec4  struct_dvec4;\n} gs_array[2];\n\nlayout (points)                   in;\nlayout (points, max_vertices = 1) out;\n\nvoid main()\n{\n    if (gs_double                 * gs_dvec2.x                 * gs_dvec3.x                 * gs_dvec4.x        *\n        gs_double_arr[0]          * gs_dvec2_arr[0].x          * gs_dvec3_arr[0].x          * gs_dvec4_arr[0].x *\n        gs_double_arr[1]          * gs_dvec2_arr[1].x          * gs_dvec3_arr[1].x          * gs_dvec4_arr[1].x *\n        gs_array[0].struct_double * gs_array[0].struct_dvec2.x * gs_array[0].struct_dvec3.x * gs_array[0].struct_dvec4.x *\n        gs_array[1].struct_double * gs_array[1].struct_dvec2.x * gs_array[1].struct_dvec3.x * gs_array[1].struct_dvec4.x > 1.0)\n    {\n        gl_Position = gl_in[0].gl_Position;\n    }\n    else\n    {\n        gl_Position = gl_in[0].gl_Position + vec4(1);\n    }\n\n    EmitVertex();\n}\n";

